#include <cstdio>
#include <string>
#include <iostream>
#include <algorithm>

int main() {
    std::string s;
    if (!std::getline(std::cin, s)) { printf("0\n"); return 0; }
    int last[256];
    std::fill(last, last + 256, -1);
    int best = 0, l = 0;
    for (int r = 0; r < (int)s.size(); ++r) {
        unsigned char c = (unsigned char)s[r];
        if (last[c] >= l) l = last[c] + 1;
        last[c] = r;
        best = std::max(best, r - l + 1);
    }
    printf("%d\n", best);
    return 0;
}
